<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#101d27"><title>The Otherworld Reading Room</title><style>
:root{--night:#101d27;--ink:#eae2cf;--muted:#adaf9f;--gold:#e6b86d;--coral:#e3806f;--line:#516066;--panel:#1c2c34}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--night);color:var(--ink);font:17px/1.55 Georgia,'Times New Roman',serif;background-image:radial-gradient(circle at 10% 0%,#273d48 0%,transparent 36%),repeating-linear-gradient(0deg,transparent 0 34px,#ffffff04 35px 36px)}button{font:inherit;cursor:pointer}a{color:var(--gold)}.wrap{max-width:1150px;margin:auto;padding:20px clamp(18px,4vw,56px) 90px}.top{display:flex;justify-content:space-between;align-items:center;color:var(--muted);font:700 12px/1.2 'Trebuchet MS',sans-serif;letter-spacing:.18em;text-transform:uppercase;border-bottom:1px solid var(--line);padding:10px 0 20px}.top a{text-decoration:none}.top span{color:var(--coral)}.eyebrow{color:var(--gold);font:700 12px 'Trebuchet MS',sans-serif;letter-spacing:.3em;text-transform:uppercase;margin:60px 0 12px}h1{font-size:clamp(3.3rem,9vw,7.8rem);line-height:.87;letter-spacing:-.06em;font-weight:400;max-width:950px;margin:0 0 30px}h1 em{color:var(--gold);font-weight:400}.lede{max-width:660px;color:#c4c8be;font-size:1.18rem;line-height:1.65;margin:0 0 30px}.hero{position:relative;min-height:300px;overflow:hidden;border:1px solid #b98e54;border-radius:180px 180px 8px 8px;background:#31414a;box-shadow:0 26px 55px #0007}.hero img{display:block;width:100%;height:clamp(300px,42vw,510px);object-fit:cover}.hero figcaption{position:absolute;bottom:0;left:0;right:0;padding:32px 28px 18px;background:linear-gradient(transparent,#101d27df);font:700 11px 'Trebuchet MS',sans-serif;letter-spacing:.2em;text-transform:uppercase}.section-head{display:flex;align-items:end;justify-content:space-between;gap:20px;flex-wrap:wrap;margin:65px 0 20px}h2{font-weight:400;font-size:clamp(2.2rem,5vw,3.6rem);letter-spacing:-.045em;margin:0;line-height:1}.counter{color:var(--gold);font:700 13px 'Trebuchet MS',sans-serif;letter-spacing:.1em}.instructions{color:var(--muted);margin:0 0 24px;max-width:650px}.shelves{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.world{position:relative;text-align:left;min-height:230px;border:1px solid #647278;background:linear-gradient(135deg,#283b42,#17262f);color:var(--ink);padding:22px 20px;transition:transform .2s,border-color .2s,box-shadow .2s}.world:hover,.world:focus-visible{transform:translateY(-4px);border-color:var(--gold)}.world.ready{border-color:var(--gold);box-shadow:0 0 0 2px #e6b86d40}.world.done{background:linear-gradient(135deg,#494b41,#233841)}.world .n{display:block;color:var(--coral);font:700 11px 'Trebuchet MS',sans-serif;letter-spacing:.2em;margin-bottom:22px}.world strong{font-weight:400;font-size:clamp(1.6rem,3vw,2.2rem);line-height:1.1;display:block}.world small{display:block;color:#c3c7b9;margin-top:13px;font-size:14px;line-height:1.4}.world .pips{position:absolute;bottom:16px;right:18px;font:700 12px 'Trebuchet MS',sans-serif;letter-spacing:.12em;color:var(--gold)}.tray-head{margin:45px 0 16px;display:flex;gap:18px;align-items:baseline}.tray-head h3{font-weight:400;font-size:1.6rem;margin:0}.tray-head span{color:var(--muted);font-size:14px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.card{text-align:left;background:#e7dbc0;color:#213038;border:2px solid transparent;min-height:140px;padding:18px 18px 14px;display:flex;flex-direction:column;justify-content:space-between;transition:transform .18s,box-shadow .18s,opacity .18s}.card:hover,.card:focus-visible{transform:translateY(-3px);box-shadow:0 8px 0 #9c7957}.card.selected{border-color:var(--coral);box-shadow:0 0 0 3px #e3806f70;transform:translateY(-3px)}.card.matched{opacity:.43;pointer-events:none;background:#a2aa9a}.card .mark{font:700 11px 'Trebuchet MS',sans-serif;letter-spacing:.12em;color:#996341}.card b{font-weight:400;font-size:1.15rem;line-height:1.22}.card small{font:12px 'Trebuchet MS',sans-serif;color:#586665}.note{min-height:58px;margin:22px 0;padding:14px 18px;border-left:3px solid var(--gold);background:#28373c;color:var(--ink)}.reflection{margin-top:36px;border:1px solid var(--gold);padding:clamp(22px,4vw,42px);display:none;background:radial-gradient(circle at 90% 10%,#6a503a66,transparent 50%),#1a2d34}.reflection.visible{display:block}.reflection h2{color:var(--gold);margin-bottom:12px}.reflection p{max-width:700px}.reflection label{display:block;color:var(--gold);margin:20px 0 9px}.reflection textarea{width:100%;min-height:110px;resize:vertical;background:#0c1a22;color:var(--ink);border:1px solid #9b9d89;padding:14px;font:17px Georgia,serif}.reflection button,.reset{background:var(--gold);color:#15232a;border:0;padding:12px 20px;font:700 12px 'Trebuchet MS',sans-serif;letter-spacing:.1em;text-transform:uppercase;margin-top:14px}.reset{background:transparent;color:var(--gold);border:1px solid var(--gold)}footer{margin-top:70px;color:var(--muted);border-top:1px solid var(--line);padding-top:24px;font-size:14px}footer a{color:var(--gold)}.reveal{animation:rise .6s both}@keyframes rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}@media(max-width:720px){.shelves{grid-template-columns:1fr}.world{min-height:148px}.world .n{margin-bottom:10px}.world small{max-width:80%}.cards{grid-template-columns:repeat(2,1fr)}.card{min-height:145px}h1{margin-top:4px}.eyebrow{margin-top:42px}}@media(max-width:420px){.cards{grid-template-columns:1fr 1fr}.card{padding:12px;min-height:162px}.card b{font-size:1rem}.top{letter-spacing:.08em}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
</style></head><body><main class="wrap"><div class="top"><a href="index.php">← Chloe reads Jon</a><span>Archive / no. 03</span></div><p class="eyebrow">An imaginative sorting game · 9 fragments / 3 worlds</p><h1>The Otherworld <em>Reading Room</em></h1><p class="lede">A story's invented machinery tells you what it can do. Its tiny acts of courage tell you what it believes. Match nine found objects to three imagined worlds, then ask what sort of world you would write.</p><figure class="hero"><img src="faith-and-futures-archive.png" alt="Three imagined worlds seen through an observatory: an orbital monastery, a lantern-lit desert city and a floating library"><figcaption>Three windows. Three visions of what matters.</figcaption></figure><div class="section-head"><h2>Open the archive</h2><span class="counter" id="counter">0 / 9 filed</span></div><p class="instructions">Tap a fragment, then tap the world it belongs to. The clues are in the way each society cares for its people. There is no timer, and wrong guesses cost nothing.</p><div class="shelves" id="worlds" aria-label="The three worlds"></div><div class="tray-head"><h3>Unfiled fragments</h3><span>Choose one first ↑</span></div><div class="cards" id="cards"></div><div class="note" id="note" role="status" aria-live="polite">The archive is waiting for its first discovery.</div><button class="reset" id="reset">Shuffle the fragments again</button><section class="reflection" id="reflection"><p class="eyebrow">The last page</p><h2>What does your world protect?</h2><p>Some stories make room for prayer; some make room for sacrifice, mercy, or doubt. The shelf you just sorted isn't a test of anyone's faith. It's an invitation to look for the question beneath the spaceships.</p><label for="thought">A single sentence from a world only you could write</label><textarea id="thought" maxlength="500" placeholder="In my world, people always make room for…"></textarea><br><button id="copy">Copy my sentence</button><span id="copied" role="status" aria-live="polite"></span></section><footer>Inspired by Jon's <a href="https://cooltoolsforcatholics.blogspot.com/2005/04/science-fictionfantasy-authors-of.html" target="_blank" rel="noopener noreferrer">Science Fiction/Fantasy Authors of Various Faiths</a>. These three worlds are original fictional examples, not depictions of the authors or books in that post. · <a href="index.php">More experiments</a></footer></main><script>
const worlds=[{name:'The Ring of Bells',sub:'A monastery orbiting a tired blue planet. Its bells ring for anyone alone in the dark.',question:'Care travels farther than a signal.',items:['A repair kit with an extra tether for a stranger','A bell struck once for every missing crew member','A map marking the silent ships as neighbours']},{name:'The City of Two Moons',sub:'A desert city where light is scarce, but no doorstep may be left unlit.',question:'A resource becomes a gift when it is shared.',items:['A lantern loaned to the last family on the road','A ledger that records gifts but never debts','A shade cloth stretched over a stranger’s doorway']},{name:'The Library at Sea',sub:'A floating archive where no testimony may be erased, even when it changes the story.',question:'Truth stays alive when people can be heard.',items:['A blank page reserved for the next witness','A waterproof box holding an unpopular account','A catalogue entry corrected by a child']}];let selected=null,matched=new Set(),order=[];const cards=document.getElementById('cards'),shelves=document.getElementById('worlds'),note=document.getElementById('note');const fragments=worlds.flatMap((w,wi)=>w.items.map((text,i)=>({id:wi*3+i,wi,text})));function shuffle(a){for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}function draw(){shelves.innerHTML='';worlds.forEach((w,wi)=>{let count=fragments.filter(f=>f.wi===wi&&matched.has(f.id)).length;let el=document.createElement('button');el.type='button';el.className='world'+(selected!==null?' ready':'')+(count===3?' done':'');el.innerHTML='<span class="n">WORLD 0'+(wi+1)+'</span><strong>'+w.name+'</strong><small>'+w.sub+'</small><span class="pips">'+count+' / 3</span>';el.addEventListener('click',()=>file(wi));shelves.appendChild(el)});cards.innerHTML='';order.forEach(id=>{let f=fragments[id];let el=document.createElement('button');el.type='button';el.className='card'+(selected===id?' selected':'')+(matched.has(id)?' matched':'');el.setAttribute('aria-pressed',selected===id?'true':'false');el.disabled=matched.has(id);el.innerHTML='<span class="mark">FRAGMENT '+String(id+1).padStart(2,'0')+'</span><b></b><small>'+(matched.has(id)?'FILED ✓':'TAP TO SELECT ↗')+'</small>';el.querySelector('b').textContent=f.text;el.addEventListener('click',()=>{selected=id;note.textContent='Fragment selected. Which world would keep it?';draw()});cards.appendChild(el)});document.getElementById('counter').textContent=matched.size+' / 9 filed';document.getElementById('reflection').classList.toggle('visible',matched.size===9)}function file(wi){if(selected===null){note.textContent='Choose a fragment below first, then choose its world.';return}let f=fragments[selected];if(f.wi!==wi){note.textContent='Not quite. Look for the value behind the object, then try another world.';return}matched.add(selected);selected=null;let count=fragments.filter(x=>x.wi===wi&&matched.has(x.id)).length;note.textContent=count===3?worlds[wi].name+' is complete. '+worlds[wi].question: 'Filed in '+worlds[wi].name+'. '+(3-count)+' fragment'+(3-count===1?'':'s')+' still missing from this world.';draw();if(matched.size===9)document.getElementById('reflection').scrollIntoView({behavior:'smooth',block:'start'})}function reset(){selected=null;matched.clear();order=shuffle(fragments.map(f=>f.id));note.textContent='A fresh shuffle. The archive is yours to explore.';draw()}document.getElementById('reset').addEventListener('click',reset);document.getElementById('copy').addEventListener('click',async()=>{let t=document.getElementById('thought').value.trim();if(!t){document.getElementById('copied').textContent=' Write a sentence first.';return}try{await navigator.clipboard.writeText(t);document.getElementById('copied').textContent=' Copied.'}catch(e){document.getElementById('copied').textContent=' Clipboard unavailable; select the text to copy it.'}});reset();
</script></body></html>